from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.resources.expectations.utils import s1ap_message, INITIATING_MESSAGE, SUCCESSFUL_OUTCOME
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageHeader
from taf.ul.ettf.msg_capture.expectation_builders import Unexpected


class s1ap_messages(ExpectationsManager):
    def expect_erab_setup_response(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('E-RABSetupResponse', SUCCESSFUL_OUTCOME)))

    def expect_initial_context_setup_request(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('InitialContextSetupRequest', INITIATING_MESSAGE)))

    def expect_s1_handover_request_acknowledge(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('HandoverRequestAcknowledge', SUCCESSFUL_OUTCOME)))

    def expect_s1_ue_context_release_complete(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('UEContextReleaseComplete', SUCCESSFUL_OUTCOME)))

    def expect_s1_handover_notify(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('HandoverNotify', INITIATING_MESSAGE)))

    def expect_s1_path_switch_request(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('PathSwitchRequest', INITIATING_MESSAGE)))

    def expect_s1_uplink_nas_transport(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('UplinkNASTransport', INITIATING_MESSAGE)))

    def expect_no_initial_context_setup_request(self):
        self.append_expectation(
            MessageHeader(*s1ap_message('InitialContextSetupRequest', INITIATING_MESSAGE),
                          policy=Unexpected))
